Let $C = \tilde{O}_{\alpha}(1)$ be the constant in the density increment case of \cref{prop:weakerincrement} ($C$ is fixed as $\alpha$ is given). Recall that $\tilde{O}_{\alpha'}(1)$ is short for $C_1 \log(2/\alpha')^{C_2}$, which is a decreasing function of $\alpha'$. Thus, if we use \cref{prop:weakerincrement} with some pair $\ensuremath{\mathcal{A}}' \subset \ensuremath{\mathcal{B}}'$ having relative density $\alpha' \geq \alpha$ and the second case applies, we will have a density increment of strength $[1, (\alpha')^{-1}; C]$.

We inductively construct two sequences $(A_n)$ and $(B_n)$, where, for each $n$, $A_n$ is a subset of $B_n$ with relative density $\alpha_n$. Let $A_0 = A$ and $B_0 = B$. Assume that $A_i$ and $B_i$ have been constructed for $i<n$. We use \cref{prop:weakerincrement} with $\ensuremath{\mathcal{A}} = A_{n-1}$ and $\ensuremath{\mathcal{B}} = B_{n-1}$. If the first case of the proposition holds, we stop the construction. Otherwise, we are in the density increment case and there are sets $A_n \subset B_n$ such that
\begin{itemize}
	\item $A_{n}$ is a subset of a translate of $A_{n-1}$;
	\item $A_n$ is a subset of $B_n$ of relative density $\alpha_n \geq (1+C^{-1})\alpha_{n-1}$;
	\item $B_n$ is a regular Bohr set of the form 
	\begin{equation}
		\label{eq:inters1weaker}
		B_n = (S_n B_{n-1}^{\star})_{\rho_n} \cap \widetilde{B}_{n},
	\end{equation}
	where 
	\begin{itemize}
		\item $B_{n-1}^{\star}$ is the Bohr set
		\begin{equation}
		\label{eq:inters2weaker}
		B_{n-1}^{\star}:= B_{n-1} \cap T_2 B_{n-1}\cap T_3 B_{n-1},
		\end{equation}
		whose rank we denote by $d_{n-1}^{\star}$,
		\item $S_n$ is either $\mathrm{Id}_G$, $T_2^{-1}$ or $T_3^{-1}$,
		\item $\widetilde{B}_n = \mathrm{Bohr}(\widetilde{\Gamma}_n, \widetilde{\nu}_n)$, where $|\widetilde{\Gamma}_{n}| \leq C\alpha^{-1}$ and 
	\begin{equation}
	\label{eq:boundwidthweaker}
	\bigg(\frac{\rho_n}{4}\bigg)^{d_{n-1}^{\star}}\prod_{\gamma \in \widetilde{\Gamma}_n} \frac{\widetilde{\nu}_n(\gamma)}{8} \geq  \exp \left(-\tilde{O}_{\alpha} \left(d_{n-1}^{\star}+\alpha^{-1}\right) \log\left(d_{n-1}^{\star}\right)\right).
	\end{equation}
	\end{itemize}
\end{itemize}

Note that, since $1\geq \alpha_n \geq (1+C^{-1})^n\alpha$, this construction must terminate in $l = \tilde{O}_{\alpha}(1)$ steps. We then arrive at $A_l\subset B_l$, for which 
\begin{equation}
\label{eq:TAAAweaker}
T(A, A, A) \geq T(A_l, A_l, A_l) \gg \exp \left(-\tilde{O}_{\alpha} \left(d_l \log(2d_l)\right) \right) \mu(B_l^{\star})^2,
\end{equation}
where $d_l$ is the rank of $B_l$ and, as usual, $B_l^{\star} = B_{l} \cap T_2 B_{l}\cap T_3 B_{l}$.

Let $W_i$ be the set of all automorphisms obtained by composing $i$ elements of $\{\mathrm{Id}_{G}, T_2, T_3, T_2^{-1}, T_3^{-1}\}$. Since $T_3 = -\mathrm{Id}_{G} - T_2$, these automorphisms commute, which implies that $|W_i| \leq (2i+1)^2$.

An immediate induction using \cref{eq:inters1weaker,eq:inters2weaker} shows that 
\begin{equation}
\label{eq:Bohrsetsweaker}
B_i^{\star} \supset \Bigg(\bigcap_{T\in W_{2i+1}} (TB)_{\rho_1\cdots \rho_i}\Bigg)  \cap\Bigg( \bigcap_{j=1}^{i} \bigcap_{T\in W_{2i+1}} (T \widetilde{B}_j)_{\rho_{j+1}\cdots \rho_i} \Bigg)
\end{equation}
for $0\leq i\leq l$. The same reasoning shows that the frequency set of $B_i$ is contained in 
\begin{equation*}
\Bigg(\bigcup_{T\in W_{2i}} T\Gamma\Bigg)  \cup\Bigg( \bigcup_{j=1}^{i} \bigcup_{T\in W_{2i}} T \widetilde{\Gamma}_j\Bigg).
\end{equation*}
This shows that
\begin{equation*}
d_{l} \ll l^2 d + l^3 C\alpha^{-1} = \tilde{O}_{\alpha}(d  + \alpha^{-1}).
\end{equation*}
In particular, \cref{eq:boundwidthweaker} becomes
\begin{equation}
\label{eq:boundwidthweaker3}
	\bigg(\frac{\rho_n}{4}\bigg)^{d_{n-1}^{\star}}\prod_{\gamma \in \widetilde{\Gamma}_n} \frac{\widetilde{\nu}_n(\gamma)}{8} \geq   \exp \left( -\tilde{O}_{\alpha} \left(d+\alpha^{-1}\right)\log (2d) \right),
\end{equation}
for $1\leq n \leq l$. 

We now use \cref{lem:boundbohr} to give a lower bound for $\mu(B_l^{\star})$. By \cref{eq:Bohrsetsweaker}, we have 
\begin{equation*}
\mu(B_l^{\star}) \geq \left(\Bigg(\frac{1}{4}\prod_{j=1}^{l} \rho_j\Bigg)^d\prod_{\gamma\in \Gamma} \frac{\nu(\gamma)}{8}\right)^{|W_{2l+1}|} \cdot \prod_{j=1}^{l}\left( \Bigg(\frac{1}{4}\prod_{n=j+1}^{l} \rho_n\Bigg)^{\mathrm{rk}(\widetilde{B}_j)}\prod_{\gamma\in \widetilde{\Gamma}_j} \frac{\widetilde{\nu}_j(\gamma)}{8}\right)^{|W_{2l+1}|}.
\end{equation*}
Using \cref{eq:boundwidthweaker3} and the simple inequalities $d\leq d_{j-1}^{\star}$ and $\mathrm{rk}(\widetilde{B}_j) \leq d_{n-1}^{\star}$ for $j\geq 1$ and $j+1\leq n\leq l$, this yields
\begin{equation*}
\mu(B_l^{\star}) \geq  \exp \left( -\tilde{O}_{\alpha} \left(d+\alpha^{-1}\right)\log (2d) \right) \Bigg(\prod_{\gamma\in \Gamma} \frac{\nu(\gamma)}{8}\Bigg)^{\tilde{O}_{\alpha}(1)}.
\end{equation*}
Together with \cref{eq:TAAAweaker}, this concludes the proof of \cref{thm:weakerbound}.

\begin{equation}
		\label{eq:inters2weaker}
		B_{n-1}^{\star}:= B_{n-1} \cap T_2 B_{n-1}\cap T_3 B_{n-1},
		\end{equation}

\begin{equation}
\label{eq:TAAAweaker}
T(A, A, A) \geq T(A_l, A_l, A_l) \gg \exp \left(-\tilde{O}_{\alpha} \left(d_l \log(2d_l)\right) \right) \mu(B_l^{\star})^2,
\end{equation}

\label{lem:progressions}
There is a constant $c > 0$ such that the following holds. Let $0 < \alpha \leq 1$. Let $B$ be a regular Bohr set of rank $d$, and $B'$ another regular Bohr set such that \blue{$T_3B' \subset B_{\rho}$}, with $\rho \leq c\alpha/d$. Let \blue{$A_1 \subset B$, $A_2\subset T_2^{-1}B$} and $A_3 \subset B'$, each time with relative density in $[\alpha/2, 2\alpha]$. Then either 
\begin{enumerate}
	\item (many solutions) $\blue{T(A_1, A_2, A_3)} \geq \tfrac{1}{16} \alpha^3 \mu(B) \mu(B')$, or
	\item (large $L^2$ mass on a spectrum) there is some $\eta \gg \alpha$ such that
	\begin{equation*}
	\sum_{\gamma \in \Delta_\eta (\blue{-T_3A_3})} |\mh{A/B}(\gamma)|^2 \gtrsim_{\alpha} \eta^{-1} \mu(B)^{-1},
	\end{equation*}
	where \blue{$A$ is either $A_1$ or $T_2A_2$}.
\end{enumerate}

We have 
\begin{equation*}
T(A_1, A_2, A_3) = \inner{\ind{A_1} * \ind{T_2A_2}}{\ind{-T_3A_3}} \geq \tfrac{1}{8}\alpha^3 \mu(B)^2\mu(B') \inner{\m{A_1} * \m{T_2A_2}}{\m{-T_3A_3}}.
\end{equation*}
Replacing $\m{A_1}$ and $\m{T_2A_2}$ with their balanced functions $\m{A_1/B}$ and $\m{T_2A_2/B}$, we have 
\begin{align*}
\inner{\m{A_1} * \m{T_2A_2}}{\m{-T_3A_3}} &= \inner{\m{A_1/B} * \m{T_2A_2/B}}{\m{-T_3A_3}} + E,
\end{align*}
where
\begin{equation*}
E = \inner{\m{A_1} * \m{B}}{\m{-T_3A_3}}+ \inner{\m{B} * \m{T_2A_2}}{\m{-T_3A_3}}- \inner{\m{B} * \m{B}}{\m{-T_3A_3}}.
\end{equation*}
We can estimate $E$ using regularity. Since $-T_3A_3\subset B_{\rho}$, we have $\norm{\m{-T_3A_3} * \m{B} - \m{B}}_1 = O(\rho d)$ by \cite[Lemma~4.5]{BS}. Moreover, $\norm{\m{A_1}}_{\infty}, \norm{\m{T_2A_2}}_{\infty}, \norm{\m{B}}_{\infty} \leq 2\alpha^{-1}\mu(B)^{-1}$. Therefore
\begin{align*}
E&= \inner{\m{A_1} }{\m{-T_3A_3} * \m{B}} + \inner{ \m{T_2A_2}}{\m{-T_3A_3}* \m{B}}- \inner{\m{B}}{\m{-T_3A_3}* \m{B}}\\
&= \inner{\m{A_1} }{\m{B}} + \inner{ \m{T_2A_2}}{\m{B}}- \inner{\m{B}}{\m{B}} + O(\rho d\alpha^{-1} \mu(B)^{-1})\\
&= \mu(B)^{-1} + \mu(B)^{-1}  - \mu(B)^{-1} +O\big(\rho d\alpha^{-1} \mu(B)^{-1}\big)\\
&= \mu(B)^{-1} + O\left(\rho d\alpha^{-1} \mu(B)^{-1}\right).
\end{align*}
In particular, $E\geq \frac{3}{4}\mu(B)^{-1}$, provided $\rho$ is small enough. Thus 
\begin{equation*}
T(A_1, A_2, A_3) \geq \tfrac{1}{8}\alpha^3 \mu(B)^2\mu(B') \Big(\inner{\m{A_1/B} * \m{T_2A_2/B}}{\m{-T_3A_3}} + \tfrac{3}{4}\mu(B)^{-1} \Big)
\end{equation*}
If the first case of the conclusion doesn't hold, then
\begin{equation*}
\inner{\m{A_1/B} * \m{T_2A_2/B}}{\m{-T_3A_3}} \leq -\tfrac{1}{4} \mu(B)^{-1}.
\end{equation*}
By Parseval's identity, followed by the triangle inequality, we deduce that
\begin{equation*}
\inner{|\mh{A_1/B}| |\mh{T_2A_2/B}|}{|\mh{-T_3A_3}|}\geq \tfrac{1}{4} \mu(B)^{-1}.
\end{equation*}
Using $xy\leq \tfrac12 (x^2+y^2)$, we find that 
\begin{equation*}
\sum_{\gamma \in \widehat{G}} |\mh{A/B}(\gamma)|^2|\mh{-T_3A_3}(\gamma)| = \inner{|\mh{A/B}|^2}{|\mh{-T_3A_3}|}\geq \tfrac{1}{4} \mu(B)^{-1},
\end{equation*}
where $A$ is either $A_1$ or $T_2A_2$. Since $\norm{\m{A/B}}_2^2\leq \alpha^{-1}\mu(B)^{-1}$, we can discard the terms of the above sum with $|\mh{-T_3A_3}| \leq \tfrac{1}{8}\alpha$ to obtain
\begin{equation*}
\sum_{\gamma \in \Delta_{\alpha/8}(-T_3A_3)} |\mh{A/B}(\gamma)|^2|\mh{-T_3A_3}(\gamma)| \geq \tfrac{1}{8} \mu(B)^{-1}.
\end{equation*}
By the dyadic pigeonhole principle, we conclude that there is some $1 \geq \eta \gg \alpha$ such that 
\begin{equation*}
\sum_{\gamma \in \Delta_{\eta}(-T_3A_3) \setminus  \Delta_{2\eta}(-T_3A_3) } |\mh{A/B}(\gamma)|^2|\mh{-T_3A_3}(\gamma)| \geqs{\alpha} \mu(B)^{-1}.
\end{equation*}
This concludes the proof since $|\mh{-T_3A_3}(\gamma)| \asymp \eta$ on the set $\Delta_{\eta}(-T_3A_3) \setminus  \Delta_{2\eta}(-T_3A_3)$.

\begin{align*}
E&= \inner{\m{A_1} }{\m{-T_3A_3} * \m{B}} + \inner{ \m{T_2A_2}}{\m{-T_3A_3}* \m{B}}- \inner{\m{B}}{\m{-T_3A_3}* \m{B}}\\
&= \inner{\m{A_1} }{\m{B}} + \inner{ \m{T_2A_2}}{\m{B}}- \inner{\m{B}}{\m{B}} + O(\rho d\alpha^{-1} \mu(B)^{-1})\\
&= \mu(B)^{-1} + \mu(B)^{-1}  - \mu(B)^{-1} +O\big(\rho d\alpha^{-1} \mu(B)^{-1}\big)\\
&= \mu(B)^{-1} + O\left(\rho d\alpha^{-1} \mu(B)^{-1}\right).
\end{align*}

\label{prop:incrementOrANS}
There is a constant $c>0$ such that the following holds. Let $k, h, t\geq 20$ be some parameters. 

Let $0< \alpha\leq 1$. Let $B$ be a regular Bohr set of rank $d$, and $B'$ another regular Bohr set, of \blue{rank at most $3d$}, such that \blue{$B' \subset T_3^{-1}B_{\rho}$}, where $\rho \leq c\alpha^2/d$. Let \blue{$A_1 \subset B$, $A_2 \subset T_2^{-1}B$} and $A_3 \subset B'$, each time with relative density in $[\alpha/2, 2\alpha]$. Then \blue{for either $A = A_1$ or $A = T_2A_2$}, one of the following holds 
\begin{enumerate}
	\item (large density) $\alpha \gg 1/k^2$, or
	\item (many solutions) $\blue{T(A_1, A_2, A_3)} \gg \alpha^3 \mu(B) \mu(B')$, or
	\item $A$ has a density increment of strength either 
	\begin{enumerate}
		\item (small increment) $[1, \alpha^{-1/k}; \tilde{O}_{\alpha}(h \log t)]$ or 
		\item (large increment) $[\alpha^{-1/k}, \alpha^{-1+1/k}; \tilde{O}_{\alpha}(h \log t)]$
	\end{enumerate}
	relative to $\blue{T_3B'}$, or
	\item (non-smoothing large spectrum) there is a set $\Delta$ and three quantities ${\rho_{\mathrm{top}}, \rho_{\mathrm{bottom}}, \rho'\in (0, 1)}$ satisfying
	\begin{equation*}
	\rho_{\mathrm{top}} \gg \alpha^{O(1)}(c/dt)^{O(h)}, \quad \rho_{\mathrm{bottom}}\gg (\alpha/d)^{O(1)}, \quad \text{and}\quad \rho' \gg (\alpha/d)^{O(1)},
	\end{equation*}
	such that 
	\begin{enumerate}
		\item $\alpha^{-3 + O(1/k)} \ll |\Delta| \leqs{\alpha} \alpha^{-3}$,
		\item there exists an additive framework $\tilde{\Gamma}$ of height $h$ and tolerance $t$ between 
		\begin{equation*}
		\Gamma_{\mathrm{top}} := \Delta_{1/2}(\blue{T_3 B_{\rho_{\mathrm{top}}}'})\quad \text{and}\quad\Gamma_{\mathrm{bottom}} := \Delta_{1/2}(\blue{T_3 B_{\rho_{\mathrm{bottom}}}'}),
		\end{equation*}
		\item $\Delta$ is $\tfrac{1}{4}$-robustly $(\tau, k')$-additively non-smoothing relative to $\tilde{\Gamma}$ for some $\alpha^{2-O(1/k)} \gg \tau \gg \alpha^{2+O(1/k)}$ and $k\geq k' \gg k$, and 
		\item if we let $B'' = (\blue{T_3 B_{\rho_{\mathrm{top}}}'})_{\rho'}$ then for all $\gamma \in\Delta + \Gamma_{\mathrm{top}}$
		\begin{equation*}
		|\mh{A/B}|^2 \circ |\mh{B''}|^2 (\gamma) \gg \alpha^{2+O(1/k)} \mu(B)^{-1},
		\end{equation*}
		and
		\item \begin{equation*}
		\Big\|\ind{\Delta} \circ |\mh{B''}|^2\Big\|_{\infty} \leq 2.
		\end{equation*}
	\end{enumerate}
\end{enumerate}

We keep the notation $B^{(0)} := B'$ and $B^{(i+1)} = B^{(i)}_{\rho_i} $ for some $\rho_i$ that are the same as those in the original proof.

By \cref{lem:progressions}, either we are in the second case or there is some $\eta \gg \alpha$ such that
\begin{equation*}
	\sum_{\gamma \in \Delta_\eta (-T_3A_3)} |\mh{A/B}(\gamma)|^2 \gtrsim_{\alpha} \eta^{-1} \mu(B)^{-1},
\end{equation*}
where $A$ is either $A_1$ or $T_2A_2$.

Suppose first that this is true for some $\eta \geq \tfrac12 K^{-1}$. In this case we apply \cite[Corollary~7.11]{BS} with $T_3B'$ instead of $B$, with $T_3B^{(1)}$ in place of $B'$, the function $f$ chosen to be $\ind{-T_3A_3}$ and  and the weight function $\omega$ given by $\omega = |\mh{A/B}|^2$, restricted to $\Delta_{\eta}(-T_3A_3)$. We apply \cite[Lemma~7.8]{BS} and \cite[Lemma~5.7]{BS} in the same way as in the original proof, except that we obtain a small density increment for $A$ relative to $T_3B'$ instead of $B'$. 

The case $ \tfrac12 K^{-1}\geq \eta \geq K^2\alpha$ is similar. After using \cite[Corollary~7.12]{BS}, \cite[Lemma~7.8]{BS} and \cite[Lemma~5.7]{BS}, we conclude that $A$ has a large increment relative to $T_3B'$.

Finally, in the case $\alpha \ll \eta \ll K^2\alpha$, we have 
\begin{equation*}
\sum_{\gamma \in \tilde{\Delta}} |\mh{A/B}(\gamma)|^2 \geqs{\alpha} K^2\alpha^{-1} \mu(B)^{-1},
\end{equation*}
where $\tilde{\Delta} = \Delta_{c\alpha}(-T_3A_3)$ for some absolute constant $c>0$. We use \cite[Lemma~6.2]{BS} to construct an additive framework between $\Gamma_{\mathrm{top}} = \Delta_{1/2}(T_3B^{(2)})$ and $\Gamma_{\mathrm{bottom}} = \Delta_{1/2}(T_3B^{(1)})$. Next, we use \cite[Lemma~8.5]{BS} with $A'$ being replaced by $-T_3A_3$, $B'$ being replaced by $T_3B'$, $B^{(1)}$ being replaced by $T_3B^{(2)}$ and $B^{(2)}$ being replaced by $T_3B^{(3)}$. This either gives a density increment for $A$ with respect to $T_3B'$, or else produces a set $\Delta$ satisfying most of the conditions of the final case of \cref{prop:incrementOrANS}. The rest of the proof is the same, after replacing every occurrence of $2\cdot A'$ by $-T_3A_3$ and every occurrence of $2\cdot B^{(i)}$ by $T_3B^{(i)}$.

\label{prop:incrementOrSolutions}
There is a constant $C>0$ such that, for all $k\geq C$, the following holds. Let $\ensuremath{\mathcal{B}}$ be a regular Bohr set of rank $d$ and suppose that $\ensuremath{\mathcal{A}}\subset \ensuremath{\mathcal{B}}$ has density $\alpha$. Let $\blue{\ensuremath{\mathcal{B}}^{\star} := \ensuremath{\mathcal{B}} \cap T_2\ensuremath{\mathcal{B}} \cap T_3\ensuremath{\mathcal{B}}}$. Either 
\begin{enumerate}
	\item $\alpha \geq 2^{-O(k^2)}$, 
	\item \begin{equation*}
	T(\ensuremath{\mathcal{A}}, \ensuremath{\mathcal{A}}, \ensuremath{\mathcal{A}}) \gg \exp\left(-\tilde{O}_{\alpha}(d \log{2d})\right) \mu(\blue{\ensuremath{\mathcal{B}}^{\star}})^2,
	\end{equation*}
	or
	\item $\ensuremath{\mathcal{A}}$ has a density increment of one of the following strengths \blue{relative to $\ensuremath{\mathcal{B}}_1:=\ensuremath{\mathcal{B}}^{\star}$, $\ensuremath{\mathcal{B}}_2:=T_2^{-1}\ensuremath{\mathcal{B}}^{\star}$ or $\ensuremath{\mathcal{B}}_3:=T_3^{-1}\ensuremath{\mathcal{B}}^{\star}$}: 
	\begin{enumerate}
		\item (small increment) $[\alpha^{O(\varepsilon(k))}, \alpha^{-O(\varepsilon(k))}; \tilde{O}_{\alpha}(1)]$, or
		\item (large increment) $[\alpha^{-1/k}, \alpha^{-1+1/k}; \tilde{O}_{\alpha}(1)]$,
	\end{enumerate}
	where $\varepsilon(k) = \frac{ \log \log \log k}{\log \log k}$.
\end{enumerate}

Let $\varepsilon = c_0 \alpha^{C_0 \frac{\log\log \log k}{\log \log k}}$, for some small constant $0< c_0 \leq \frac13$ and some large constant $C_0 > 0$. We apply \cref{lem:bourgain} with
\begin{equation*}
B_1 = (\ensuremath{\mathcal{B}}^{\star})_{\rho}, \quad B_2 = T_2^{-1}(\ensuremath{\mathcal{B}}^{\star})_{\rho},\quad \text{and}\quad B_3 = T_3^{-1}(\ensuremath{\mathcal{B}}^{\star})_{\rho\rho'},
\end{equation*}
where $\rho = c\alpha\varepsilon/d$ and $\rho' = c'\alpha^2/d$ ($c$ and $c'$ being small constants, chosen in particular such that $B_1$ and $B_3$ are regular.\footnote{Note that the regularity of $B_2$ follows immediately from that of $B_1$.} If we are in the second case of \cref{lem:bourgain}, then $\ensuremath{\mathcal{A}}$ has a small increment with respect to $B_1$, $B_2$ or $B_3$. By \cref{lem:relativeincrements}, this translates into a density increment of the same strength with respect to $\ensuremath{\mathcal{B}}_1$, $\ensuremath{\mathcal{B}}_2$ or $\ensuremath{\mathcal{B}}_3$, as required. 

Let us assume henceforth that we are in the first case of \cref{lem:bourgain}. Let
\begin{equation*}
A_1 = (\ensuremath{\mathcal{A}} - x) \cap B_1, \quad A_2 = (\ensuremath{\mathcal{A}} - x) \cap B_2\quad \text{and}\quad A_3 = (\ensuremath{\mathcal{A}} - x) \cap B_3.
\end{equation*}
If $\alpha_i$ is the density of $A_i$ relative to $B_i$, for $1\leq i\leq 3$, then \cref{lem:bourgain} ensures that 
\begin{equation*}
\alpha_i \in [(1-\varepsilon)\alpha, (1+\varepsilon)\alpha].
\end{equation*}

We now apply \cref{prop:incrementOrANS} with $B = B_1$, $B' = B_3$, $h = \lceil c_1 \log\log k/\log\log \log k\rceil$ and $t = \lceil C_2 \log k\rceil$, for some suitable constants $c_1, C_2 > 0$. 
\begin{enumerate}
	\item In the first case of the conclusion of \cref{prop:incrementOrANS}, $\alpha \gg 1/k^2 \geq 2^{-O(k^2)}$.
	\item In the second case, 
	\begin{equation*}
	T(A_1, A_2, A_3) \gg \alpha^3 \mu(B_1) \mu(B_3) \gg \exp\left(-\tilde{O}_{\alpha}(d\log 2d)\right) \mu(\ensuremath{\mathcal{B}}^{\star})^2
	\end{equation*}
	by \cref{lem:boundbohr}. Since the $A_i$'s are subsets of the same translate of $\ensuremath{\mathcal{A}}$ and the equation $a_1+T_2a_2+T_3a_3 = 0$ is translation-invariant, we have $T(\ensuremath{\mathcal{A}}, \ensuremath{\mathcal{A}}, \ensuremath{\mathcal{A}}) \geq T(A_1, A_2, A_3)$ and we are done.
	\item In the third case, either $A_1\subset B_1$ or $T_2A_2\subset B_1$ has a density increment of strength 
	\begin{equation*}
	[1, \alpha^{-1/k}; \tilde{O}_{\alpha}(h \log t)]\quad \text{or}\quad[\alpha^{-1/k}, \alpha^{-1+1/k}; \tilde{O}_{\alpha}(h \log t)]
	\end{equation*}
	with respect to $T_3B_3 = (B_1)_{\rho'}$. Note that $h \log t = \tilde{O}_{\alpha}(1)$, or else we have the first case of the conclusion. Therefore, $\ensuremath{\mathcal{A}}$ has a density increment of strength 
	\begin{equation*}
	[1, \alpha^{-1/k}; \tilde{O}_{\alpha}(1)]\quad \text{or}\quad[\alpha^{-1/k}, \alpha^{-1+1/k}; \tilde{O}_{\alpha}(1)]
	\end{equation*}
	relative to either $(B_1)_{\rho'}$ or $T_2^{-1}(B_1)_{\rho'} = (B_2)_{\rho'}$ (here we use the fact that $\varepsilon$ is sufficiently small, similarly as in \cref{eq:epsilonchoice}). By \cref{lem:relativeincrements}, this implies that $\ensuremath{\mathcal{A}}$ has an increment of the same strength relative to $\ensuremath{\mathcal{B}}_1$ or $\ensuremath{\mathcal{B}}_2$.
	\item Finally, suppose that the last case of the conclusion of \cref{prop:incrementOrANS} holds. Then we may apply \cite[Proposition~11.8]{BS} with $B = B_1$, $B' = (T_3B_3)_{\rho_{\mathrm{top}}}$ and $B'' = (T_3B_3)_{\rho_{\mathrm{top}}\rho'}$. The hypotheses of \cite[Proposition~11.8]{BS} exactly match the last case of \cref{prop:incrementOrANS} for some $K = \alpha^{-O(1/k)}$.

	The number $M$ in \cite[Proposition~11.8]{BS} satisfies $M = \alpha^{-O(\varepsilon(k))}$, or else $\alpha \geq 2^{-O(k^2)}$ and we are in the first case of our conclusion. Taking $C$ large enough in the statement of \cref{prop:incrementOrSolutions}, we see that the first case of \cite[Proposition~11.8]{BS} cannot hold. In the other two cases, either $A_1\subset B_1$ or $T_2A_2\subset B_1$ has a density increment of strength 
	\begin{equation*}
	[\alpha^{O(\varepsilon(k))}, \alpha^{-O(\varepsilon(k))}; \tilde{O}_{\alpha}(1)]\quad \text{or}\quad[\alpha^{-1/k}, \alpha^{-1+1/k}; \tilde{O}_{\alpha}(1)]
	\end{equation*}
	with respect to $B''$. As in the previous case, we conclude that $\ensuremath{\mathcal{A}}$ has a density increment of the same strength with respect to $\ensuremath{\mathcal{B}}_1$ or $\ensuremath{\mathcal{B}}_2$.\qedhere
\end{enumerate}

\begin{equation*}
A_1 = (\ensuremath{\mathcal{A}} - x) \cap B_1, \quad A_2 = (\ensuremath{\mathcal{A}} - x) \cap B_2\quad \text{and}\quad A_3 = (\ensuremath{\mathcal{A}} - x) \cap B_3.
\end{equation*}

Let $A\subset G$ of density $\alpha$. In this proof, $\alpha$ will always denote the density of this initial $A$.

Let $1\leq C_1 = O(1)$ be some absolute constant, chosen in particular larger than the implied constants in the exponents of the small increment case of \cref{prop:incrementOrSolutions}. Let $k$ be some constant large enough such that \cref{prop:incrementOrSolutions} holds and such that $8C_1\varepsilon(k) \leq 1/2$. Let $1\leq C_2 = \tilde{O}_{\alpha}(1)$ be some fixed quantity (depending only on $\alpha$), chosen in particular larger than the implicit constants of \cref{prop:incrementOrSolutions} hidden in the $\gg$, $O(\cdot)$ and $\tilde{O}_{\alpha}(1)$ notation. By definition of $\tilde{O}_{\alpha}(\cdot)$, these implicit constants are still bounded by $C_2$ if we use \cref{prop:incrementOrSolutions} with some different relative density $\alpha'$, as long as $\alpha' \geq \alpha$. Note that we may assume that $2^{C_2k^2} \leq \alpha^{-1/2}$, or else we are done by an application of \cref{thm:weakerbound} with $B = G$.

\medbreak\textbf{Iterative construction.}
We inductively construct two sequences $(A_n)$ and $(B_n)$, where, for each $n$, $A_n$ is a subset of $B_n$ relative density $\alpha_n$. Let $A_0 = A$ and $B_0 = G$. Assume that $A_i$ and $B_i$ have been constructed for $i<n$. We use \cref{prop:incrementOrSolutions} with $\ensuremath{\mathcal{A}} = A_{n-1}$ and $\ensuremath{\mathcal{B}} = B_{n-1}$. If we are not in case (3)(a), then we stop the construction of the sequences. Otherwise, case (3)(a) occurs, and we have a small increment for $A_n$. Hence, there are sets $A_n \subset B_n$ such that
\begin{itemize}
	\item $A_{n}$ is a subset of a translate of $A_{n-1}$;
	\item $A_n$ is a subset of $B_n$ of relative density $\alpha_n \geq \left(1+C_2^{-1}\alpha^{C_1\varepsilon(k)}\right)\alpha_{n-1}$;
	\item $B_n$ is a regular Bohr set of the form 
	\begin{equation}
		\label{eq:inters1}
		B_n = (S_n B_{n-1}^{\star})_{\rho_n} \cap \widetilde{B}_{n},
	\end{equation}
	where \begin{itemize}
		\item $B_{n-1}^{\star}$ is the Bohr set
		\begin{equation}
		\label{eq:inters2}
		B_{n-1}^{\star}:= B_{n-1} \cap T_2 B_{n-1}\cap T_3 B_{n-1},
		\end{equation}
		whose rank we denote by $d_{n-1}^{\star}$,
		\item $S_n$ is either $\mathrm{Id}_G$, $T_2^{-1}$ or $T_3^{-1}$,
		\item $\widetilde{B}_n = \mathrm{Bohr}(\widetilde{\Gamma}_n, \widetilde{\nu}_n)$, where $|\widetilde{\Gamma}_{n}| \leq C_2\alpha^{-C_1\varepsilon(k)}$ and 
	\begin{equation}
	\label{eq:boundwidth}
	\bigg(\frac{\rho_n}{4}\bigg)^{d_{n-1}^{\star}}\prod_{\gamma \in \widetilde{\Gamma}_n} \frac{\widetilde{\nu}_n(\gamma)}{8} \geq  \exp \left(-\tilde{O}_{\alpha} \left(d_{n-1}^{\star}+\alpha^{-C_1\varepsilon(k)}\right) \log\left(d_{n-1}^{\star}\right)\right).
	\end{equation}
	\end{itemize}
\end{itemize}

\medbreak\textbf{Analysis of the algorithm.} Note that, since $1\geq \alpha_n \geq \left(1+C_2^{-1}\alpha^{C_1\varepsilon(k)}\right)^n\alpha$, this construction must terminate in
\begin{equation*}
l = \tilde{O}_{\alpha}\left(\alpha^{-C_1\varepsilon(k)}\right)
\end{equation*}
steps. We then arrive at $A_l\subset B_l$ for which one of the cases (1), (2) and (3)(b) of \cref{prop:incrementOrSolutions} applies. 


Let $W_i$ be the set of all automorphisms obtained by composing $i$ elements of $\{\mathrm{Id}_{G}, T_2, T_3, T_2^{-1}, T_3^{-1}\}$. Since $T_3 = -\mathrm{Id}_{G} - T_2$, these automorphisms commute, which implies that $|W_i| \leq (2i+1)^2$.

An immediate induction using \cref{eq:inters1,eq:inters2} shows that 
\begin{equation}
\label{eq:bohrsetsweaker}
B_i^{\star} \supset  \bigcap_{j=1}^{i} \bigcap_{T\in W_{2i+1}} (T \widetilde{B}_j)_{\rho_{j+1}\cdots \rho_i}
\end{equation}
for $0\leq i\leq l$. Similarly, we see that the frequency set of $B_i^{\star}$ is contained in 
\begin{equation*}
 \bigcup_{j=1}^{i} \bigcup_{T\in W_{2i+1}} T \widetilde{\Gamma}_j.
\end{equation*}
This implies that
\begin{equation*}
d_{l}^{\star} \ll l^3 C_2\alpha^{-C_1\varepsilon(k)} = \tilde{O}_{\alpha}\left(\alpha^{-4C_1\varepsilon(k)}\right).
\end{equation*}
In particular, \cref{eq:boundwidth} becomes
\begin{equation}
\label{eq:boundwidthweaker2}
	\bigg(\frac{\rho_n}{4}\bigg)^{d_{n-1}^{\star}}\prod_{\gamma \in \widetilde{\Gamma}_n} \frac{\widetilde{\nu}_n(\gamma)}{8} \geq   \exp \left( - \tilde{O}_{\alpha}\left(\alpha^{-4C_1\varepsilon(k)}\right) \right),
\end{equation}
for $1\leq n \leq l$. 

We now use \cref{lem:boundbohr} to give a lower bound for $\mu(B_l^{\star})$. By \cref{eq:bohrsetsweaker}, we have 
\begin{equation*}
\mu(B_l^{\star}) \geq \prod_{j=1}^{l}\Bigg( \bigg(\frac{1}{4}\prod_{n=j+1}^{l} \rho_n\bigg)^{\mathrm{rk}(\widetilde{B}_j)}\prod_{\gamma\in \widetilde{\Gamma}_j} \frac{\widetilde{\nu}_j(\gamma)}{8}\Bigg)^{|W_{2l+1}|}.
\end{equation*}
Using \cref{eq:boundwidthweaker2} and the fact that $\mathrm{rk}(\widetilde{B}_j) \leq d_{n-1}^{\star}$ for  $j+1\leq n\leq l$, this yields
\begin{equation}
\label{eq:sizelastBohrset}
\mu(B_l^{\star}) \geq  \exp \left( - \tilde{O}_{\alpha}\left(\alpha^{-4C_1\varepsilon(k)}\right) \right)^{ \tilde{O}_{\alpha}\left(\alpha^{-4C_1\varepsilon(k)} \right)} \geq  \exp \left( - \tilde{O}_{\alpha}\left(\alpha^{-8C_1\varepsilon(k)}\right) \right).
\end{equation}
If $B_l^{\star} = \mathrm{Bohr}(\Gamma_l^{\star}, \nu_l^{\star})$, this reasoning actually shows the more precise bound
\begin{equation}
\label{eq:sizelastBohrset2}
\prod_{\gamma\in \Gamma_l^{\star}} \frac{\nu_l^{\star}(\gamma)}{8} \geq \exp \left( - \tilde{O}_{\alpha}\left(\alpha^{-8C_1\varepsilon(k)}\right) \right).
\end{equation}


\medbreak\textbf{Concluding the proof.}
We now apply \cref{prop:incrementOrSolutions} to $\ensuremath{\mathcal{A}} = A_l$ and $\ensuremath{\mathcal{B}} = B_l$. The small increment case cannot occur, by construction of the sequences $(A_l)$ and $(B_l)$.
\begin{itemize}
	\item If we are in the case (1) of \cref{prop:incrementOrSolutions}, then $\alpha_l \geq 2^{-C_2k^2}$. In this case we apply \cref{thm:weakerbound} and obtain the bound
	\begin{equation*}
	T(A_l, A_l, A_l) \gg \exp \left(-\tilde{O}_{\alpha}\left(\alpha^{-4C_1\varepsilon(k)}+ 2^{C_2k^2}\right) \right) \bigg( \prod_{\gamma\in \Gamma_l} \frac{\nu_l(\gamma)}{8}\bigg)^{\tilde{O}_{\alpha}(1)},
	\end{equation*}
	where $B_l = \mathrm{Bohr}(\Gamma_l, \nu_l)$. Using \cref{eq:sizelastBohrset2}, we deduce that
	\begin{equation*}
	T(A, A, A) \geq T(A_l, A_l, A_l) \geq \exp \left( - \tilde{O}_{\alpha}\left(\alpha^{-8C_1\varepsilon(k)}+ 2^{C_2k^2}\right) \right).
	\end{equation*}

	\item In the second case, we directly obtain 
	\begin{equation*}
	T(A_l, A_l, A_l) \gg \exp \left(-\widetilde{O}_{\alpha}\left(\alpha^{-4C_1\varepsilon(k)}\right)\right) \mu(B_l)^2,
	\end{equation*}
	and thus 
	\begin{equation*}
	T(A, A, A) \geq T(A_l, A_l, A_l) \geq  \exp \left( - \tilde{O}_{\alpha}\left(\alpha^{-8C_1\varepsilon(k)}\right) \right)
	\end{equation*}
	by \cref{eq:sizelastBohrset}.
	\item Finally, in the large increment case, there are some $\rho>0$, $T\in \{\mathrm{Id}_G, T_2^{-1}, T_3^{-1}\}$ and $\widetilde{B} = \mathrm{Bohr}(\widetilde{\Gamma}, \widetilde{\nu})$ such that ${|\widetilde{\Gamma}| \leq C_2\alpha^{-1+1/k}}$ and, if 
	\begin{equation*}
	B'' := (TB_l^{\star})_{\rho} \cap \widetilde{B},
	\end{equation*}
	then $\norm{\ind{A}*\m{B''}} \geqs{\alpha} \alpha^{1-1/k}$ and
	\begin{equation}
	\label{eq:sizeboundlargeinc}
	\left(\frac{\rho}{4}\right)^{\mathrm{rk}(TB_l^{\star})} \prod_{\gamma\in \widetilde{\Gamma}} \frac{\widetilde{\nu}(\gamma)}{8} \geq \exp \left(-\tilde{O}_{\alpha}\left(\alpha^{-4C_1\varepsilon(k)}+\alpha^{-1+1/k}\right)\right).
	\end{equation}
	Write $B'' = \mathrm{Bohr}(\Gamma'', \nu'')$. Then
	\begin{align*}
	\prod_{\gamma\in \Gamma''} \frac{\nu''(\gamma)}{8} &\geq \left(\left(\frac{\rho}{4}\right)^{\mathrm{rk}(TB_l^{\star})} \prod_{\gamma\in \widetilde{\Gamma}} \frac{\widetilde{\nu}(\gamma)}{8}\right) \left(\prod_{\gamma\in \Gamma_l^{\star}} \frac{\nu_l^{\star}(\gamma)}{8}\right) \\
	&\geq \exp \left(-\tilde{O}_{\alpha}\left(\alpha^{-8C_1\varepsilon(k)}+\alpha^{-1+1/k}\right)\right)
	\end{align*}	
	by \cref{eq:sizeboundlargeinc,eq:sizelastBohrset2}. We now apply \cref{thm:weakerbound} to a suitable subset $A''$ of a translate of $A$ and the Bohr set $B''$ to find that
	\begin{align*}
	T(A'', A'', A'') &\geq \exp \left(-\tilde{O}_{\alpha}\left(\alpha^{-4C_1\varepsilon(k)}+\alpha^{-1+1/k}\right)\right) \bigg( \prod_{\gamma\in \Gamma''} \frac{\nu''(\gamma)}{8}\bigg)^{\tilde{O}_{\alpha}(1)} \\
	&\geq \exp \left(-\tilde{O}_{\alpha}\left(\alpha^{-8C_1\varepsilon(k)}+\alpha^{-1+1/k}\right)\right).
	\end{align*}
\end{itemize}
Therefore, we obtain, in all three cases, the lower bound
\begin{equation*}
T(A, A, A) \geq\exp \left(-\tilde{O}_{\alpha}\left(\alpha^{-8C_1\varepsilon(k)}+\alpha^{-1+1/k}+ 2^{C_2k^2}\right)\right).
\end{equation*}
Choosing $c = 1/(2k)$, say, we obtain 
\begin{equation*}
T(A, A, A) \geq \exp \left(-{O}(\alpha^{-1+c})\right).
\end{equation*}
On the other hand, since $A$ contains only trivial solutions to $a_1 + T_2a_2 + T_3a_3 = 0$, we have 
\begin{equation*}
T(A, A, A) = \frac{\alpha}{|G|} \leq \frac{1}{|G|}.
\end{equation*}
Therefore, $|G| \leq \exp\left({O}(\alpha^{-1+c})\right)$, which can be rewritten as
\begin{equation*}
|A| \ll \frac{|G|}{(\log{|G|})^{1+c'}},
\end{equation*}
where $c' = \frac{1}{1-c}-1$. This finishes the proof of \cref{thm:main}.

\begin{equation}
		\label{eq:inters2}
		B_{n-1}^{\star}:= B_{n-1} \cap T_2 B_{n-1}\cap T_3 B_{n-1},
		\end{equation}

\begin{equation*}
	T(A, A, A) \geq T(A_l, A_l, A_l) \geq \exp \left( - \tilde{O}_{\alpha}\left(\alpha^{-8C_1\varepsilon(k)}+ 2^{C_2k^2}\right) \right).
	\end{equation*}

\begin{equation*}
	T(A, A, A) \geq T(A_l, A_l, A_l) \geq  \exp \left( - \tilde{O}_{\alpha}\left(\alpha^{-8C_1\varepsilon(k)}\right) \right)
	\end{equation*}
